CREATE DATABASE IF NOT EXISTS hotel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hotel;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY, usuario VARCHAR(40) UNIQUE NOT NULL, clave VARCHAR(255) NOT NULL, rol ENUM('admin','recepcion') NOT NULL);
CREATE TABLE habitaciones(id INT AUTO_INCREMENT PRIMARY KEY, numero VARCHAR(10) UNIQUE NOT NULL, tipo VARCHAR(30) NOT NULL, precio DECIMAL(8,2) NOT NULL, estado ENUM('libre','ocupada','limpieza','mantenimiento') DEFAULT 'libre');
CREATE TABLE productos(id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(60) NOT NULL, categoria VARCHAR(30) NOT NULL, precio DECIMAL(8,2) NOT NULL, stock INT NOT NULL DEFAULT 0, stock_minimo INT NOT NULL DEFAULT 5, activo TINYINT DEFAULT 1);
CREATE TABLE estadias(id INT AUTO_INCREMENT PRIMARY KEY, habitacion_id INT NOT NULL, huesped VARCHAR(80) NOT NULL, dni VARCHAR(20) NULL, telefono VARCHAR(20) NULL, noches INT NOT NULL, salida_prevista DATE NOT NULL, precio_noche DECIMAL(8,2) NOT NULL, entrada TIMESTAMP DEFAULT CURRENT_TIMESTAMP, salida DATETIME NULL, estado ENUM('activa','cerrada') DEFAULT 'activa', total_hab DECIMAL(10,2) DEFAULT 0, total_prod DECIMAL(10,2) DEFAULT 0, FOREIGN KEY(habitacion_id) REFERENCES habitaciones(id));
CREATE TABLE pagos(id INT AUTO_INCREMENT PRIMARY KEY, estadia_id INT NOT NULL, monto DECIMAL(10,2) NOT NULL, metodo ENUM('Efectivo','Yape','Plin','Tarjeta') NOT NULL, tipo ENUM('adelanto','saldo') NOT NULL, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(estadia_id) REFERENCES estadias(id));
CREATE TABLE consumos(id INT AUTO_INCREMENT PRIMARY KEY, estadia_id INT NOT NULL, producto_id INT NULL, producto VARCHAR(60) NOT NULL, precio DECIMAL(8,2) NOT NULL, cantidad INT NOT NULL, FOREIGN KEY(estadia_id) REFERENCES estadias(id) ON DELETE CASCADE);
CREATE TABLE movimientos_stock(id INT AUTO_INCREMENT PRIMARY KEY, producto_id INT NOT NULL, cantidad INT NOT NULL, motivo ENUM('compra','venta','ajuste','devolucion') NOT NULL, estadia_id INT NULL, usuario VARCHAR(40) NULL, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(producto_id) REFERENCES productos(id));
